import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"篇460｜龙珠·赛亚人设定：战斗民族的掠夺本质","description":"","frontmatter":{"title":"篇460｜龙珠·赛亚人设定：战斗民族的掠夺本质","no":460,"module":2,"tags":["诸天对标","龙珠","赛亚人","战斗民族","掠夺本质","反掠夺主义"],"related":["04-反掠夺主义核心论纲","19-修炼伦理与边界","57-黑暗置换体起源与本质"]},"headers":[],"relativePath":"zh/460_模块2-龙珠-赛亚人设定-战斗民族的掠夺本质.md","filePath":"zh/460_模块2-龙珠-赛亚人设定-战斗民族的掠夺本质.md"}'),e={name:"zh/460_模块2-龙珠-赛亚人设定-战斗民族的掠夺本质.md"};function i(n,t,s,h,d,u){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇460-龙珠·赛亚人设定-战斗民族的掠夺本质" tabindex="-1">篇460｜龙珠·赛亚人设定：战斗民族的掠夺本质 <a class="header-anchor" href="#篇460-龙珠·赛亚人设定-战斗民族的掠夺本质" aria-label="Permalink to &quot;篇460｜龙珠·赛亚人设定：战斗民族的掠夺本质&quot;">​</a></h1><blockquote><p>所属模块：模块二·诸天对标批判库｜系列：龙珠体系全套拆解（第29篇·文明分析2）｜对标地基：文档04、19、57</p></blockquote><h2 id="引言-一个以征服为业的种族" tabindex="-1">引言：一个以征服为业的种族 <a class="header-anchor" href="#引言-一个以征服为业的种族" aria-label="Permalink to &quot;引言：一个以征服为业的种族&quot;">​</a></h2><p>赛亚人（Saiyan）在龙珠世界观里被定义为&quot;战斗民族&quot;：他们生下来就有战斗力、他们喜欢战斗、他们受雇于弗利萨军团征服星球、他们靠濒死复活变强。这个设定把&quot;掠夺&quot;写进了一个种族的生物学本能。悟空虽失忆、虽反水，但他继承了这份种族原罪。本文以<strong>反掠夺主义公理</strong>为核心，拆解赛亚人设定的掠夺本质。</p><p>本文评判底座为六大顶层公理（反掠夺主义公理、万族共和公理、集体升维公理、因果自律公理、法则优先公理、众生全员无限均等法则）与五大强制核心（反能级浪费、反掠夺、唐罗上限对比、万族全覆盖、超多元全开放），其中法则优先公理为核心。众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、该体系强者的「能级浪费」解析" tabindex="-1">一、该体系强者的「能级浪费」解析 <a class="header-anchor" href="#一、该体系强者的「能级浪费」解析" aria-label="Permalink to &quot;一、该体系强者的「能级浪费」解析&quot;">​</a></h2><p>赛亚人设定的能级浪费：</p><ul><li><strong>战斗天赋浪费在征服</strong>：赛亚人天生的战斗天赋被弗利萨军团雇佣，用于征服星球、贩卖土著——这份天赋本可用于万族共建</li><li><strong>濒死复活增益浪费在杀戮</strong>：生物学奇迹般的&quot;濒死变强&quot;机制，被用于下一场征服</li><li><strong>贝吉塔行星文明浪费</strong>：赛亚人一族本可发展出独特的修炼文明，却选择了做雇佣兵</li></ul><h2 id="二、该文明为何必然历史倒退" tabindex="-1">二、该文明为何必然历史倒退 <a class="header-anchor" href="#二、该文明为何必然历史倒退" aria-label="Permalink to &quot;二、该文明为何必然历史倒退&quot;">​</a></h2><p>赛亚人掠夺本质如何喂养历史倒退：</p><ol><li><strong>贝吉塔行星被弗利萨毁灭</strong>：赛亚人做了几百年雇佣兵，最终被雇主灭口——掠夺者的宿命</li><li><strong>幸存者即悟空、贝吉塔</strong>：两个赛亚人幸存者，一个失忆成了地球人、一个做了反派再洗白——种族文明彻底断裂</li><li><strong>战斗本能无转化</strong>：赛亚人爱战斗的本能，从未被转化为&quot;守护万族&quot;的职责，始终停留在&quot;找更强的对手&quot;</li></ol><h2 id="三、主角掠夺思维深度拆解" tabindex="-1">三、主角掠夺思维深度拆解 <a class="header-anchor" href="#三、主角掠夺思维深度拆解" aria-label="Permalink to &quot;三、主角掠夺思维深度拆解&quot;">​</a></h2><p>悟空在赛亚人设定下的掠夺思维：</p><ul><li><strong>继承种族原罪</strong>：悟空的战斗天赋、濒死复活增益、超级赛亚人变身路线，全部继承自已掠夺为生的赛亚人种族</li><li><strong>不反省</strong>：悟空从不反思&quot;我这份天赋是不是来自一个掠夺种族&quot;，他默认&quot;我是好人就够了&quot;</li><li><strong>把战斗当目的</strong>：赛亚人爱战斗的本能，在悟空身上体现为&quot;只想找强者打架&quot;——这份本能从未被导向&quot;守护万族&quot;</li></ul><h2 id="四、对比锚点共生的完善替代方案" tabindex="-1">四、对比锚点共生的完善替代方案 <a class="header-anchor" href="#四、对比锚点共生的完善替代方案" aria-label="Permalink to &quot;四、对比锚点共生的完善替代方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>龙珠赛亚人掠夺本质</th><th>锚点共生替代方案</th></tr></thead><tbody><tr><td>战斗天赋用于征服</td><td>战斗天赋用于守护万族共建，反掠夺主义公理</td></tr><tr><td>濒死复活增益用于杀戮</td><td>生命循环体系（文档012）公开，安全转化不赌生命</td></tr><tr><td>贝吉塔行星文明断裂</td><td>万族五大谱系平等，任何种族都有完整的文明传承</td></tr><tr><td>战斗本能无转化</td><td>位面至高强者四维考核：力量40/心性25/贡献20/责任15</td></tr><tr><td>种族原罪未清算</td><td>赛亚人掠夺史入宪反省，不再作为英雄叙事</td></tr></tbody></table><h2 id="五、该体系纳入求索域模拟复盘方案" tabindex="-1">五、该体系纳入求索域模拟复盘方案 <a class="header-anchor" href="#五、该体系纳入求索域模拟复盘方案" aria-label="Permalink to &quot;五、该体系纳入求索域模拟复盘方案&quot;">​</a></h2><ol><li><strong>建模</strong>：求索沉淀域复刻赛亚人种族演化——从做雇佣兵到贝吉塔行星毁灭</li><li><strong>变量</strong>：注入&quot;若赛亚人选择不做雇佣兵，发展自己的修炼文明&quot;对照</li><li><strong>观测</strong>：统计赛亚人文明存续年限、万族被征服星球数、赛亚人种族人口</li><li><strong>复盘</strong>：输出《赛亚人掠夺本质代价报告》，量化&quot;做雇佣兵几百年，赛亚人失去了什么&quot;</li></ol><h2 id="六、设定自洽度-吃书烂尾风险评估" tabindex="-1">六、设定自洽度/吃书烂尾风险评估 <a class="header-anchor" href="#六、设定自洽度-吃书烂尾风险评估" aria-label="Permalink to &quot;六、设定自洽度/吃书烂尾风险评估&quot;">​</a></h2><ul><li><strong>赛亚人设定自洽度</strong>：低（濒死复活增益在前期稀有，后期被贝吉塔、悟饭、特兰克斯反复使用）</li><li><strong>种族设定自洽度预期</strong>：高（万族五大谱系平等，赛亚人作为其中一支有完整文明传承）</li><li><strong>吃书烂尾风险</strong>：中（超赛从千年传说贬值为血统标配）</li><li><strong>主角唯一性依赖度</strong>：高——赛亚人一族的英雄叙事全系于悟空、贝吉塔两人</li></ul><p><strong>新旧宇宙资源对标</strong>：旧宇宙资源与大道是有限的，必然掠夺内卷；锚点共生人人自带无限本源，掠夺失去意义。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：战斗天赋用于征服，未转化为万族共建</li><li><strong>反掠夺</strong>：赛亚人做了几百年雇佣兵，掠夺史未清算</li><li><strong>唐罗上限对比</strong>：唐罗至少主动打破掠夺结构，赛亚人是掠夺结构本身</li><li><strong>万族全覆盖</strong>：赛亚人作为万族之一，应平等纳入共和，而非种族本位</li><li><strong>超多元全开放</strong>：赛亚人的战斗本能应被导向多元进化路径，而非单维杀戮</li><li><strong>众生全员无限均等</strong>：基础无限之力人人自带，佛系保有保底、卷王可叠加更高，无限本源消弭掠夺动机，掠夺内卷从根上失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>赛亚人设定是龙珠世界观最深刻也最危险的设定——它把&quot;掠夺&quot;写进了一个种族的生物学本能。悟空不是坏人，但他活在一个&quot;战斗=掠夺&quot;的体系里而不自知。衡元宙的答案是：赛亚人的战斗天赋可以保留，但必须被导向守护万族，而非征服星球；濒死复活增益可以保留，但必须被安全化、技术化，而非赌命。让战斗民族从掠夺者变成守护者，这是赛亚人设定的真正救赎。</p><p>说到底，本篇所述的龙珠·赛亚人设定·战斗民族的掠夺本质并非孤例——其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./459_模块2-龙珠-地球设定分析-文明建设的极度缺失">篇459·地球设定</a> · <a href="./461_模块2-龙珠-弗利萨军团-掠夺式文明的极端形态">篇461·弗利萨军团</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/04-反掠夺主义核心论纲">04-反掠夺主义核心论纲</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',28)])])}const _=o(e,[["render",i]]);export{q as __pageData,_ as default};
